import type {ChangeEvent} from 'react'
import {memo, useMemo, useState} from 'react'
import type {EntryPointProps} from 'react-relay'
import {graphql, useFragment, usePreloadedQuery} from 'react-relay'

import useEventCallback from '../../../../../hooks/useEventCallback'
import ParametersGroupControls from '../../../../packages/Parameters/components/GroupControls/ParametersGroupControls'
import ParametersPageHeader from '../../../../packages/Parameters/components/PageHeader/ParametersPageHeader'
import {ParametersTree} from '../../../../packages/Parameters/components/ParametersTree/ParametersTree'
import ParametersSearch from '../../../../packages/Parameters/components/Search/ParametersSearch'
import {ParameterCategory, ParameterGroup} from '../../../../packages/Parameters/Parameters.types'
import {useFilterSearch} from '../../../../packages/Parameters/utils/filterSearch'

import type {AgentTypeParameters_agentType$key} from './__generated__/AgentTypeParameters_agentType.graphql'
import type {AgentTypeParametersQuery} from './__generated__/AgentTypeParametersQuery.graphql'
import {query} from './AgentTypeParameters.queries'

import styles from './AgentTypeParameters.module.css'

import {inlineListMaxLength} from 'src/components/packages/Parameters/Parameters.consts'

const fragment = graphql`
  fragment AgentTypeParameters_agentType on AgentTypeRest {
    environmentParameters {
      count
      ...filterSearch_parameters
    }
    systemParameters {
      count
      ...filterSearch_parameters
    }
    configurationParameters {
      count
      ...filterSearch_parameters
    }
  }
`

interface Props {
  agentTypeKey: AgentTypeParameters_agentType$key | null
}

function AgentTypeParametersComponent(props: Props) {
  const {agentTypeKey} = props
  const {
    configurationParameters = null,
    systemParameters = null,
    environmentParameters = null,
  } = useFragment(fragment, agentTypeKey) ?? {}

  const [search, setSearch] = useState('')

  const configurationItems = useFilterSearch({parametersKey: configurationParameters, search})
  const systemItems = useFilterSearch({parametersKey: systemParameters, search})
  const environmentItems = useFilterSearch({parametersKey: environmentParameters, search})

  const parameters = useMemo(
    () => [
      {
        category: ParameterCategory.AGENT_TYPE,
        groups: [
          {
            group: ParameterGroup.CONFIGURATION,
            withDescription: true,
            header: {
              value: 'Value',
            },
            items: configurationItems,
          },
          {
            group: ParameterGroup.SYSTEM,
            withDescription: true,
            header: {
              value: 'Value',
            },
            items: systemItems,
          },
          {
            group: ParameterGroup.ENVIRONMENT,
            withDescription: true,
            header: {
              value: 'Value',
            },
            items: environmentItems,
          },
        ],
      },
    ],
    [configurationItems, environmentItems, systemItems],
  )

  const handleChangeSearch = useEventCallback((event: ChangeEvent<HTMLInputElement>) => {
    setSearch(event.currentTarget.value)
  })

  const handleClearSearch = useEventCallback(() => {
    setSearch('')
  })

  const totalParametersCount =
    (configurationParameters?.count ?? 0) +
    (systemParameters?.count ?? 0) +
    (environmentParameters?.count ?? 0)
  const isVirtualized = totalParametersCount > inlineListMaxLength

  return (
    <>
      <ParametersPageHeader>
        <ParametersSearch
          value={search}
          onChange={handleChangeSearch}
          onClear={handleClearSearch}
        />
        <ParametersGroupControls className={styles.controls} />
      </ParametersPageHeader>

      <ParametersTree highlight={search} parameters={parameters} isVirtualized={isVirtualized} />
    </>
  )
}

type Queries = {main: AgentTypeParametersQuery}
const AgentTypeParameters = memo(function AgentTypeParameters({
  queries,
}: EntryPointProps<Queries, {}, {}, {}>) {
  const {agentType = null} = usePreloadedQuery(query, queries.main)
  return <AgentTypeParametersComponent agentTypeKey={agentType} />
})
export default AgentTypeParameters
export type AgentTypeParametersComponentType = typeof AgentTypeParameters
